#=====================================================
# PARK TOOLHEAD
#=====================================================
# INSTRUCTIONS: To change the park location, simply modify the numbers in the X_POS, Y_POS, Z_POS, and SPEED variables below.
# @DESC Homes the printer (if not already homed) and parks the toolhead at a designated safe location.
[gcode_macro PARK]
gcode:
    {% set X_POS = printer.toolhead.axis_minimum.x + 10 %}
    {% set Y_POS = printer.toolhead.axis_minimum.y + 10 %}
    {% set Z_POS = printer.toolhead.axis_maximum.z - 5 %}
    {% set SPEED = 6000 %}

    {% if "xyz" not in printer.toolhead.homed_axes %}
        G28                            ; home if not already homed
    {% endif %}
    G90                              ; absolute positioning
    G0 X{X_POS} Y{Y_POS} Z{Z_POS} F{SPEED}

#=====================================================
# PID_HOTEND
#=====================================================
# @DESC Homes, moves the nozzle to the center of the bed near the surface, turns the cooling fan to 100%, and runs a thermal PID tuning cycle for the extruder. Uses the TEMP parameter or defaults to 200°C.
[gcode_macro PID_HOTEND]
description: Calibrate PID Hotend
gcode:
    {% set TEMP = params.TEMP|default(200)|float %}
    {% set X_MID = printer.toolhead.axis_maximum.x / 2 %}
    {% set Y_MID = printer.toolhead.axis_maximum.y / 2 %}
    {% if "xyz" not in printer.toolhead.homed_axes %}
      G28
    {% endif %}
    G90
    G1 X{X_MID} Y{Y_MID} F3000
    G1 Z10 F500
    M106 S255
    PID_CALIBRATE HEATER=extruder TARGET={TEMP}

#=====================================================
# PID_HOTBED
#=====================================================
# @DESC Homes, moves the nozzle to the center of the bed near the surface, turns the cooling fan to 100%, and runs a thermal PID tuning cycle for the heated bed. Uses the TEMP parameter or defaults to 60°C.
[gcode_macro PID_HOTBED]
description: Calibrate PID Hotbed
gcode:
    {% set TEMP = params.TEMP|default(60)|float %}
    {% set X_MID = printer.toolhead.axis_maximum.x / 2 %}
    {% set Y_MID = printer.toolhead.axis_maximum.y / 2 %}
    {% if "xyz" not in printer.toolhead.homed_axes %}
      G28
    {% endif %}
    G90
    G1 X{X_MID} Y{Y_MID} F3000
    G1 Z10 F500
    M106 S255
    PID_CALIBRATE HEATER=heater_bed TARGET={TEMP}
